const data = require('fs').readFileSync(0, 'utf8');

const SZ = 300;
const vis = [];
for (let i = 0; i < SZ; i++) {
    vis.push(new Array(SZ).fill(1));
}
const f = [[0, 1], [1, 0], [0, -1], [-1, 0]];

// min-heap by step
const heap = [];
function less(a, b) {
    return a.step < b.step;
}
function push(node) {
    heap.push(node);
    let i = heap.length - 1;
    while (i > 0) {
        const p = (i - 1) >> 1;
        if (less(heap[i], heap[p])) {
            const tmp = heap[i]; heap[i] = heap[p]; heap[p] = tmp;
            i = p;
        } else break;
    }
}
function top() {
    return heap[0];
}
function pop() {
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    let i = 0;
    const n = heap.length;
    while (true) {
        const l = 2 * i + 1, r = 2 * i + 2;
        let m = i;
        if (l < n && less(heap[l], heap[m])) m = l;
        if (r < n && less(heap[r], heap[m])) m = r;
        if (m === i) break;
        const tmp = heap[i]; heap[i] = heap[m]; heap[m] = tmp;
        i = m;
    }
}

function bfs(l, u, xi, yi) {
    push({ x: l, y: u, step: 0 });
    vis[l][u] = 1;
    while (heap.length > 0) {
        const e = top(); pop();
        if (e.x === xi && e.y === yi) return e.step;
        for (let i = 0; i < 4; i++) {
            const tx = e.x + f[i][0];
            const ty = e.y + f[i][1];
            const tstep = e.step + 1;
            if (tx < 0 || ty < 0) continue;
            if (vis[tx][ty]) continue;
            vis[tx][ty] = 1;
            push({ x: tx, y: ty, step: tstep });
        }
    }
    return -1;
}

function main() {
    const s = data.split(/\s+/).filter(x => x.length > 0)[0];
    const len = s.length;
    let x = 0, y = 0, xx = 0, yy = 0;
    for (let i = 0; i < len; i++) {
        if (s[i] === 'L') y--;
        if (s[i] === 'R') y++;
        if (s[i] === 'U') x--;
        if (s[i] === 'D') x++;
        xx = Math.min(xx, x);
        yy = Math.min(yy, y);
    }
    xx = -xx; yy = -yy;
    for (let i = 0; i < 110; i++) {
        for (let j = 0; j < 110; j++) vis[i][j] = 1;
    }
    x = xx; y = yy;
    for (let i = 0; i < len; i++) {
        if (s[i] === 'L') y--;
        if (s[i] === 'R') y++;
        if (s[i] === 'U') x--;
        if (s[i] === 'D') x++;
        vis[x][y] = 0;
    }
    const ans = bfs(xx, yy, x, y);

    if (ans === len) process.stdout.write("OK\n");
    else process.stdout.write("BUG\n");
}

main();
